import "./field.css";

import {
  useId,
  type ComponentProps,
  type ReactNode,
} from "react";
import { cx } from "./cx";

export function describedBy(
  ...parts: Array<string | false | null | undefined>
): string | undefined {
  const value = parts.filter((part): part is string => Boolean(part)).join(" ");
  return value || undefined;
}

export const TEXT_FIELD_TYPES = [
  "text",
  "email",
  "password",
  "url",
  "tel",
  "search",
  "number",
] as const;

export type TextFieldType = (typeof TEXT_FIELD_TYPES)[number];

export type FieldChrome = {
  label: ReactNode;
  optional?: boolean | undefined;
  required?: boolean | undefined;
  description?: ReactNode | undefined;
  error?: ReactNode | undefined;
  className?: string | undefined;
  chrome?: "float" | "placeholder" | undefined;
};

export type FieldKind = "well" | "choice" | "select";

export type FieldProps = FieldChrome & {
  disabled?: boolean | undefined;
  readOnly?: boolean | undefined;
  multiline?: boolean | undefined;
  kind?: FieldKind | undefined;
  inputId: string;
  descriptionId: string;
  errorId: string;
  invalid: boolean;
  children: ReactNode;
};

export type TextFieldProps = Omit<
  ComponentProps<"input">,
  "size" | "className" | "placeholder" | "type"
> &
  FieldChrome & {
    type?: TextFieldType | undefined;
  };

export type TextAreaProps = Omit<
  ComponentProps<"textarea">,
  "className" | "placeholder"
> &
  FieldChrome;

type TypeDefaults = Pick<
  ComponentProps<"input">,
  "autoCapitalize" | "autoComplete" | "enterKeyHint" | "spellCheck"
>;

function isTextFieldType(type: string): type is TextFieldType {
  return (TEXT_FIELD_TYPES as readonly string[]).includes(type);
}

function resolveType(type: string | undefined): TextFieldType {
  const next = type ?? "text";
  if (isTextFieldType(next)) return next;
  if (process.env.NODE_ENV !== "production") {
    console.warn(
      `TextField: type="${type}" is not supported. Use text, email, password, url, tel, search, or number.`,
    );
  }
  return "text";
}

function LabelMark({
  optional,
  required,
}: {
  optional?: boolean | undefined;
  required?: boolean | undefined;
}) {
  if (optional) {
    return <span className="ns-field__optional"> Optional</span>;
  }
  if (required) {
    return <span className="ns-field__required"> Required</span>;
  }
  return null;
}

function defaultsForType(type: string | undefined): TypeDefaults {
  switch (type) {
    case "email":
      return {
        spellCheck: false,
        autoCapitalize: "off",
        autoComplete: "email",
      };
    case "password":
      return {
        spellCheck: false,
        autoCapitalize: "off",
        autoComplete: "current-password",
      };
    case "url":
      return {
        spellCheck: false,
        autoCapitalize: "off",
        autoComplete: "url",
      };
    case "tel":
      return { spellCheck: false, autoComplete: "tel" };
    case "search":
      return { enterKeyHint: "search", autoComplete: "off" };
    default:
      return {};
  }
}

export function Field({
  label,
  optional,
  required,
  description,
  error,
  className,
  chrome = "float",
  disabled,
  readOnly,
  multiline,
  kind = "well",
  inputId,
  descriptionId,
  errorId,
  invalid,
  children,
}: FieldProps) {
  const placeholder = kind === "well" && chrome === "placeholder";
  const mark = <LabelMark optional={optional} required={required} />;

  return (
    <div
      className={cx("ns-field", className)}
      data-invalid={invalid ? "true" : undefined}
      data-disabled={disabled ? "true" : undefined}
      data-readonly={readOnly ? "true" : undefined}
      data-multiline={multiline ? "true" : undefined}
      data-kind={kind === "well" ? undefined : kind}
      data-label={placeholder ? "placeholder" : undefined}
    >
      {placeholder ? (
        <label className="ns-sr ns-field__sr" htmlFor={inputId}>
          {label}
          {mark}
        </label>
      ) : null}
      <div className="ns-field__control">
        {children}
        {placeholder ? null : (
          <label className="ns-field__label" htmlFor={inputId}>
            {label}
            {mark}
          </label>
        )}
      </div>
      {kind === "well" || description != null || error != null ? (
        <div className="ns-field__meta">
          {description != null ? (
            <div className="ns-field__description" id={descriptionId}>
              {description}
            </div>
          ) : null}
          {error != null ? (
            <div className="ns-field__error" id={errorId} role="alert">
              {error}
            </div>
          ) : null}
        </div>
      ) : null}
    </div>
  );
}

export function TextField({
  label,
  optional,
  required,
  description,
  error,
  className,
  chrome,
  id,
  type = "text",
  disabled,
  readOnly,
  "aria-describedby": ariaDescribedBy,
  "aria-invalid": ariaInvalid,
  ...rest
}: TextFieldProps) {
  const generatedId = useId();
  const inputId = id ?? generatedId;
  const descriptionId = `${inputId}-desc`;
  const errorId = `${inputId}-error`;
  const resolvedType = resolveType(type);
  const invalid = error != null || ariaInvalid === true || ariaInvalid === "true";
  const placeholder =
    chrome === "placeholder" && typeof label === "string" ? label : " ";

  return (
    <Field
      label={label}
      optional={optional}
      required={required}
      description={description}
      error={error}
      className={className}
      chrome={chrome}
      disabled={disabled}
      readOnly={readOnly}
      inputId={inputId}
      descriptionId={descriptionId}
      errorId={errorId}
      invalid={invalid}
    >
      <input
        {...defaultsForType(resolvedType)}
        {...rest}
        id={inputId}
        className="ns-field__input"
        type={resolvedType}
        placeholder={placeholder}
        disabled={disabled}
        readOnly={readOnly}
        required={required}
        aria-required={required || undefined}
        aria-invalid={invalid || undefined}
        aria-errormessage={error != null ? errorId : undefined}
        aria-describedby={describedBy(
          description != null && descriptionId,
          error != null && errorId,
          ariaDescribedBy,
        )}
      />
    </Field>
  );
}

export function TextArea({
  label,
  optional,
  required,
  description,
  error,
  className,
  chrome,
  id,
  disabled,
  readOnly,
  rows = 4,
  "aria-describedby": ariaDescribedBy,
  "aria-invalid": ariaInvalid,
  ...rest
}: TextAreaProps) {
  const generatedId = useId();
  const inputId = id ?? generatedId;
  const descriptionId = `${inputId}-desc`;
  const errorId = `${inputId}-error`;
  const invalid = error != null || ariaInvalid === true || ariaInvalid === "true";
  const placeholder =
    chrome === "placeholder" && typeof label === "string" ? label : " ";

  return (
    <Field
      label={label}
      optional={optional}
      required={required}
      description={description}
      error={error}
      className={className}
      chrome={chrome}
      disabled={disabled}
      readOnly={readOnly}
      multiline
      inputId={inputId}
      descriptionId={descriptionId}
      errorId={errorId}
      invalid={invalid}
    >
      <textarea
        {...rest}
        id={inputId}
        className="ns-field__input"
        placeholder={placeholder}
        disabled={disabled}
        readOnly={readOnly}
        rows={rows}
        required={required}
        aria-required={required || undefined}
        aria-invalid={invalid || undefined}
        aria-errormessage={error != null ? errorId : undefined}
        aria-describedby={describedBy(
          description != null && descriptionId,
          error != null && errorId,
          ariaDescribedBy,
        )}
      />
    </Field>
  );
}

@layer components {
  .ns-field {
    --ns-field-fg: var(--text-heading, #111);
    --ns-field-body: var(--text-body, #444);
    --ns-field-muted: var(--text-sub, #767676);
    --ns-field-fill: var(--bg, #fff);
    --ns-field-line: var(
      --line,
      color-mix(in srgb, var(--ns-field-fg) 12%, transparent)
    );
    --ns-field-line-strong: var(
      --focus,
      color-mix(in srgb, var(--text-heading, #111) 70%, transparent)
    );
    --ns-field-error: var(--error, #8f3232);
    --ns-field-radius: var(--radius, 0.4rem);
    --ns-field-inset-y: var(--space-5, 0.61rem);
    --ns-field-inset-x: var(--space-6, 0.76rem);

    display: flex;
    flex-direction: column;
    gap: var(--space-2, 0.31rem);
    min-width: 0;
    padding-top: var(--space-3, 0.39rem);
    color: var(--ns-field-body);
  }

  [data-density="compact"] .ns-field {
    --ns-field-inset-y: var(--space-3, 0.39rem);
    --ns-field-inset-x: var(--space-4, 0.49rem);
    padding-top: var(--space-2, 0.31rem);
  }

  .ns-field__control {
    position: relative;
    box-sizing: border-box;
    min-width: 0;
    height: calc(1em * var(--leading, 1.5625) + var(--ns-field-inset-y) * 2);
    border: 1px solid var(--ns-field-line);
    border-radius: var(--ns-field-radius);
    background: var(--ns-field-fill);
    box-shadow: var(--well);
    transition:
      border-color var(--duration, 200ms) var(--ease, cubic-bezier(0.22, 1, 0.36, 1)),
      box-shadow var(--duration, 200ms) var(--ease, cubic-bezier(0.22, 1, 0.36, 1));
  }

  .ns-field__control:focus-within {
    border-color: var(--ns-field-line-strong);
    outline: 2px solid var(--ns-field-line-strong);
    outline-offset: 2px;
  }

  .ns-field[data-invalid="true"] .ns-field__control {
    border-color: var(--ns-field-error);
  }

  .ns-field[data-disabled="true"] .ns-field__control {
    border-style: dashed;
  }

  .ns-field[data-readonly="true"]:not([data-disabled="true"]) .ns-field__control {
    border-style: dotted;
  }

  .ns-field[data-multiline="true"] .ns-field__control {
    height: auto;
  }

  .ns-field[data-label="placeholder"] .ns-field__input::placeholder {
    color: var(--ns-field-muted);
    opacity: 1;
  }

  .ns-field[data-kind="choice"] {
    padding-top: 0;
  }

  .ns-field[data-kind="choice"] .ns-field__control {
    display: flex;
    flex-direction: row;
    align-items: center;
    gap: var(--space-4, 0.49rem);
    height: auto;
    border: 0;
    background: none;
    box-shadow: none;
    border-radius: 0;
  }

  .ns-field[data-kind="choice"] .ns-field__label {
    position: static;
    transform: none;
    max-width: none;
    overflow: visible;
    text-overflow: unset;
    white-space: normal;
    color: var(--ns-field-fg);
    cursor: pointer;
    padding: 0;
    background: none;
  }

  .ns-field[data-kind="select"] .ns-field__label {
    transform: translateY(-50%) scale(calc(1 / var(--ratio, 1.25)));
    color: var(--ns-field-fg);
    background: var(--ns-field-fill);
    padding: 0 var(--space-2, 0.31rem);
    max-width: calc(100% - var(--space-8, 1.19rem));
  }

  .ns-field[data-kind="group"] {
    margin: 0;
    padding-top: 0;
    border: 0;
    min-width: 0;
  }

  .ns-field[data-disabled="true"][data-kind="choice"] .ns-field__label {
    color: var(--text-disabled, var(--ns-field-muted));
    cursor: not-allowed;
  }

  .ns-field__legend {
    padding: 0;
    color: var(--ns-field-fg);
    font: inherit;
    line-height: var(--leading, 1.5625);
  }

  .ns-field__options {
    display: flex;
    flex-direction: column;
    gap: var(--space-3, 0.39rem);
    min-width: 0;
  }

  .ns-field__sr {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
  }

  .ns-field__input {
    appearance: none;
    display: block;
    box-sizing: border-box;
    width: 100%;
    height: 100%;
    margin: 0;
    padding: var(--ns-field-inset-y) var(--ns-field-inset-x);
    border: 0;
    border-radius: inherit;
    background: transparent;
    color: var(--ns-field-fg);
    font: inherit;
    line-height: inherit;
    letter-spacing: inherit;
  }

  .ns-field__input:focus,
  .ns-field__input:focus-visible {
    outline: none;
  }

  .ns-field__input:disabled {
    color: var(--text-disabled, var(--ns-field-muted));
    cursor: not-allowed;
  }

  select.ns-field__input {
    appearance: none;
    cursor: pointer;
    padding-inline-end: calc(var(--ns-field-inset-x) + 1.2em);
    background-image: linear-gradient(
        45deg,
        transparent 50%,
        var(--ns-field-fg) 50%
      ),
      linear-gradient(135deg, var(--ns-field-fg) 50%, transparent 50%);
    background-position:
      calc(100% - 0.95em) calc(50% - 0.12em),
      calc(100% - 0.7em) calc(50% - 0.12em);
    background-size: 0.28em 0.28em, 0.28em 0.28em;
    background-repeat: no-repeat;
  }

  .ns-choice {
    appearance: none;
    display: inline-grid;
    place-content: center;
    box-sizing: border-box;
    flex-shrink: 0;
    width: 1.1em;
    height: 1.1em;
    margin: 0;
    padding: 0;
    border: 1px solid var(--ns-field-line);
    border-radius: calc(var(--ns-field-radius) * 0.7);
    background: var(--ns-field-fill);
    box-shadow: var(--well);
    color: var(--ns-on-key, var(--on-ink, #fff));
    cursor: pointer;
    transition:
      border-color var(--duration, 200ms) var(--ease, cubic-bezier(0.22, 1, 0.36, 1)),
      box-shadow var(--duration, 200ms) var(--ease, cubic-bezier(0.22, 1, 0.36, 1)),
      background var(--duration, 200ms) var(--ease, cubic-bezier(0.22, 1, 0.36, 1));
  }

  .ns-choice::after {
    content: "";
    width: 0.28em;
    height: 0.48em;
    border: solid currentColor;
    border-width: 0 0.12em 0.12em 0;
    transform: rotate(45deg) translate(-0.04em, -0.06em);
    opacity: 0;
  }

  .ns-choice[type="radio"] {
    border-radius: 999px;
  }

  .ns-choice[type="radio"]::after {
    width: 0.42em;
    height: 0.42em;
    border: 0;
    border-radius: 999px;
    background: currentColor;
    transform: none;
  }

  .ns-choice:checked {
    --ns-key: var(--ink, #111);
    --ns-on-key: var(--on-ink, #fff);
    --key-face: linear-gradient(
      180deg,
      color-mix(in srgb, var(--ns-key) 68%, var(--shine, #fff)) 0%,
      var(--ns-key) 52%,
      color-mix(in srgb, var(--ns-key) 82%, oklch(0 0 0)) 100%
    );
    border-color: color-mix(in srgb, var(--ns-key) 28%, transparent);
    background: var(--key-face);
    box-shadow: var(--press);
  }

  .ns-choice:checked::after {
    opacity: 1;
  }

  .ns-choice[data-kind="switch"] {
    width: 2em;
    height: 1.15em;
    border-radius: 999px;
  }

  .ns-choice[data-kind="switch"]::after {
    width: 0.72em;
    height: 0.72em;
    border: 0;
    border-radius: 999px;
    background: var(
      --face,
      linear-gradient(180deg, #fff 0%, #f3f2f1 100%)
    );
    box-shadow: var(--raise);
    transform: translateX(-0.36em);
    opacity: 1;
    transition: transform var(--duration, 200ms) var(--ease, cubic-bezier(0.22, 1, 0.36, 1));
  }

  .ns-choice[data-kind="switch"]:checked::after {
    background: var(--ns-on-key, var(--on-ink, #fff));
    box-shadow: var(--flat);
    transform: translateX(0.36em);
  }

  .ns-choice:focus,
  .ns-choice:focus-visible {
    outline: none;
  }

  .ns-field[data-kind="choice"] .ns-field__control:focus-within {
    border-color: transparent;
    outline: none;
  }

  .ns-choice:focus-visible {
    outline: 2px solid var(--ns-field-line-strong);
    outline-offset: 2px;
  }

  .ns-field[data-invalid="true"] .ns-choice {
    border-color: var(--ns-field-error);
  }

  .ns-choice:disabled {
    color: var(--text-disabled, var(--ns-field-muted));
    cursor: not-allowed;
  }

  .ns-field__input::placeholder {
    color: transparent;
    opacity: 0;
  }

  textarea.ns-field__input {
    height: auto;
    resize: vertical;
    min-height: calc(
      var(--type-md, 1rem) * var(--leading, 1.5625) * 4 + var(--ns-field-inset-y) *
        2
    );
    line-height: var(--leading, 1.5625);
  }

  .ns-field__input::-webkit-search-decoration,
  .ns-field__input::-webkit-search-cancel-button {
    appearance: none;
  }

  .ns-field__input:-webkit-autofill,
  .ns-field__input:-webkit-autofill:hover,
  .ns-field__input:-webkit-autofill:focus {
    -webkit-text-fill-color: var(--ns-field-fg);
    caret-color: var(--ns-field-fg);
    box-shadow: 0 0 0 1000px var(--ns-field-fill) inset;
    transition: background-color 9999s ease-in-out 0s;
  }

  .ns-field__label {
    position: absolute;
    z-index: 1;
    inset-inline-start: var(--ns-field-inset-x);
    top: 0;
    transform: translateY(
      calc(0.5em * var(--leading, 1.5625) + var(--ns-field-inset-y) - 50%)
    );
    max-width: calc(100% - var(--ns-field-inset-x) * 2);
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    color: var(--ns-field-muted);
    cursor: text;
    transform-origin: inline-start center;
    transition:
      transform var(--duration, 200ms) var(--ease, cubic-bezier(0.22, 1, 0.36, 1)),
      color var(--duration, 200ms) var(--ease, cubic-bezier(0.22, 1, 0.36, 1));
  }

  .ns-field[data-multiline="true"] .ns-field__label {
    transform: translateY(var(--ns-field-inset-y));
  }

  .ns-field__input:focus + .ns-field__label,
  .ns-field__input:not(:placeholder-shown) + .ns-field__label,
  .ns-field__input:-webkit-autofill + .ns-field__label {
    transform: translateY(-50%) scale(calc(1 / var(--ratio, 1.25)));
    color: var(--ns-field-fg);
    background: var(--ns-field-fill);
    padding: 0 var(--space-2, 0.31rem);
    max-width: calc(100% - var(--space-8, 1.19rem));
  }

  .ns-field[data-invalid="true"] .ns-field__input:focus + .ns-field__label,
  .ns-field[data-invalid="true"] .ns-field__input:not(:placeholder-shown) + .ns-field__label,
  .ns-field[data-invalid="true"] .ns-field__input:-webkit-autofill + .ns-field__label {
    color: var(--ns-field-error);
  }

  .ns-field__optional,
  .ns-field__required {
    color: var(--ns-field-muted);
  }

  .ns-field__meta {
    min-height: 1.6em;
    min-height: 1lh;
    line-height: var(--leading, 1.5625);
  }

  .ns-field__description,
  .ns-field__error {
    overflow-wrap: anywhere;
  }

  .ns-field__description {
    color: var(--ns-field-muted);
  }

  .ns-field__error {
    color: var(--ns-field-error);
  }

  @media (prefers-reduced-motion: reduce) {
    .ns-field__control,
    .ns-field__label {
      transition: none;
    }
  }
}
